#!/usr/bin/env python3
"""Emit one conservative JSON snapshot for each Linux hwmon fan input."""
import json
import re
import time
from pathlib import Path

ROOT = Path("/sys/class/hwmon")
COLLECTOR = "linux_hwmon_fan_v1"
INPUT_RE = re.compile(r"^(fan[1-9][0-9]*)_input$")
TEXT_ATTRIBUTES = {"label"}
VALUE_FIELDS = {
    "label": "fan_label",
    "min": "min_rpm",
    "max": "max_rpm",
    "target": "target_rpm",
}
OPTIONAL_ATTRIBUTES = (
    "label", "min", "max", "target", "pulses", "div", "enable",
    "alarm", "min_alarm", "max_alarm", "fault",
)


def emit(status, observed_at_epoch, **fields):
    event = {
        "event_version": 1,
        "collector": COLLECTOR,
        "collector_status": status,
        "observed_at_epoch": observed_at_epoch,
    }
    event.update(fields)
    print(json.dumps(event, ensure_ascii=True, separators=(",", ":"), sort_keys=True), flush=True)


def read_text(path):
    return path.read_text(encoding="ascii", errors="strict").strip()


def read_nonnegative_integer(path):
    value = int(read_text(path), 10)
    if value < 0:
        raise ValueError(f"negative hwmon value: {path.name}")
    return value


def optional_value(directory, channel, suffix):
    path = directory / f"{channel}_{suffix}"
    value_field = VALUE_FIELDS.get(suffix, suffix)
    result = {f"{suffix}_present": 1 if path.is_file() else 0, f"{suffix}_read_ok": 0}
    if not path.is_file():
        result[value_field] = None
        return result, 0
    try:
        value = read_text(path) if suffix in TEXT_ATTRIBUTES else read_nonnegative_integer(path)
    except (OSError, UnicodeError, ValueError):
        result[value_field] = None
        return result, 1
    result[f"{suffix}_read_ok"] = 1
    result[value_field] = value
    return result, 0


def stable_device_path(resolved_hwmon):
    if resolved_hwmon.parent.name == "hwmon":
        return str(resolved_hwmon.parent.parent)
    return str(resolved_hwmon.parent)


def main():
    observed = int(time.time())
    if not ROOT.is_dir():
        emit("unsupported", observed, error_path=str(ROOT))
        return
    fan_count = 0
    for class_path in sorted(ROOT.glob("hwmon*")):
        try:
            resolved = class_path.resolve(strict=True)
            chip_name = read_text(class_path / "name")
        except (OSError, UnicodeError) as exc:
            emit("chip_read_error", observed, hwmon_class=class_path.name, error_class=type(exc).__name__)
            continue
        device_path = stable_device_path(resolved)
        chip_key = f"{chip_name}|{device_path}"
        for input_path in sorted(class_path.glob("fan*_input")):
            match = INPUT_RE.fullmatch(input_path.name)
            if not match:
                continue
            fan_count += 1
            channel = match.group(1)
            base = {
                "hwmon_class": class_path.name,
                "device_path": device_path,
                "chip_name": chip_name,
                "chip_key": chip_key,
                "fan_channel": channel,
                "input_present": 1,
            }
            try:
                input_rpm = read_nonnegative_integer(input_path)
            except (OSError, UnicodeError, ValueError) as exc:
                emit("input_read_error", observed, input_read_ok=0, input_rpm=None, error_class=type(exc).__name__, **base)
                continue
            fields = {"input_read_ok": 1, "input_rpm": input_rpm, **base}
            optional_errors = 0
            for suffix in OPTIONAL_ATTRIBUTES:
                values, failed = optional_value(class_path, channel, suffix)
                fields.update(values)
                optional_errors += failed
            fields["optional_read_errors"] = optional_errors
            emit("ok", observed, **fields)
    if fan_count == 0:
        emit("no_fan_inputs", observed, error_path=str(ROOT))


if __name__ == "__main__":
    main()
